#include <iostream>
#include <vector>

int count_positive(const std::vector<int>& values) {
    int count = 0;
    for (const int value : values) {
        if (value > 0) {
            count += 1;
        }
    }
    return count;
}

int main() {
    const std::vector<int> values = { 3, -1, 2 };
    std::cout << count_positive(values) << "\n";
    return 0;
}
